const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',diamond:'m12 3 8 6-8 12L4 9z M4 9h16 M8 4l4 17 4-17',box:'m3 7 9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',order:'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4',transfer:'M3 7h16l-4-4 M21 17H5l4 4 M19 7l-4 4 M5 17l4-4',sync:'M20 7a9 9 0 0 0-15-2L2 8 M2 3v5h5 M4 17a9 9 0 0 0 15 2l3-3 M22 21v-5h-5',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',chart:'M4 20V4 M4 20h17 M8 16v-4 M13 16V8 M18 16V5',store:'M3 10h18l-2-6H5z M5 10v10h14V10 M9 20v-6h6v6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c-5 5-5 13 0 18 M12 3c5 5 5 13 0 18',bell:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5z M10 21h4',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',check:'M5 12l4 4L19 6',service:'M14 4a5 5 0 0 0-6 6L3 17l4 4 7-7a5 5 0 0 0 6-6l-4 3-3-3z',close:'M6 6l12 12 M18 6 6 18',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M18 4a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.diamond}"/></svg>`;
const nav=[['overview','Overview','grid'],['inventory','Inventory','diamond'],['reservations','Reservations & orders','order'],['transfers','Branch transfers','transfer'],['inward','Procurement & inward','box'],['channels','Channel sync','sync'],['service','Returns & repairs','service'],['audits','Audits & approvals','shield'],['reports','Reports & insights','chart']];
const names=['Temple Lakshmi Necklace','Heritage Gold Bangles','Solitaire Diamond Ring','Antique Jhumka Earrings','Everyday Gold Chain','Ruby Floral Pendant','Classic Diamond Bracelet','Traditional Kasu Mala','Rose Gold Band','Emerald Drop Earrings','Gold Coin · 10 gram','Diamond Stud Earrings','Heritage Vanki Ring','Pearl Gold Choker','Gold Kada','Bridal Long Necklace'];
const branches=['Puttur','Mangaluru','Bengaluru','Madikeri'];
const items=names.map((name,i)=>({id:`GDI-${String(2401+i)}`,name,category:['Necklaces','Bangles','Rings','Earrings','Chains','Pendants','Bracelets','Necklaces','Rings','Earrings','Coins','Earrings','Rings','Necklaces','Bangles','Necklaces'][i],branch:branches[i%4],purity:[2,6,8,11].includes(i)?'18K · 750':'22K · 916',weight:[42.65,28.4,4.82,18.32,12.54,6.72,14.2,56.8,3.65,9.24,10,5.6,7.82,32.45,24.7,64.5][i],value:[426500,284000,185000,183200,125400,82000,245000,568000,46500,152000,100000,128000,78200,324500,247000,645000][i],status:i===2||i===7?'Reserved':i===10?'In transit':i===13?'Quarantine':'Available',owner:i===13?'Supplier':'Company',age:[34,62,18,92,25,114,43,145,12,67,8,42,183,5,54,98][i]}));
let holds=[{id:'RSV-1084',piece:'GDI-2403',channel:'Website',customer:'Customer •• 042',state:'Payment pending'},{id:'RSV-1085',piece:'GDI-2408',channel:'Showroom',customer:'Customer •• 017',state:'Deposit received'}];
let transfers=[{id:'TRF-0281',piece:'GDI-2411',from:'Bengaluru',to:'Puttur',state:'In transit',seal:'SEAL-0841'}];
let history=[['check','Inward inspection completed','GDI-2401 · Puttur','10:42 AM'],['sync','Website availability verified','12 saleable pieces published','10:38 AM'],['transfer','Transfer dispatched','TRF-0281 · Bengaluru → Puttur','10:24 AM']];
let route='overview',filter={query:'',status:'All statuses',branch:'All branches'},syncRetried=false,approvalDone=false;
const fmt=v=>'₹'+v.toLocaleString('en-IN');
const badge=s=>`<span class="badge ${/pending|Reserved|transit|Waiting|Review|Deposit|Payment/i.test(s)?'amber':/Quarantine|exception|mismatch|Missing/i.test(s)?'red':/Closed|Cancelled/i.test(s)?'gray':''}">${s}</span>`;
const btn=(label,action,primary=false,ic='')=>`<button type="button" ${primary?'class="primary"':''} onclick="${action}">${ic?icon(ic):''}${label}</button>`;
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3500)}
function go(r){location.hash=r;document.body.classList.remove('menu-open')}
function count(s){return items.filter(i=>i.status===s).length}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">GOLD &amp; DIAMONDS / OMNICHANNEL</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function stats(){return `<div class="stats">${[['Total physical stock',items.length,'pieces','Across 4 demo branches','box'],['Available to sell',count('Available'),'pieces','Eligible for central reservation','diamond'],['Inventory value', '₹'+(items.filter(x=>x.owner==='Company').reduce((s,i)=>s+i.value,0)/100000).toFixed(2),'L','Company-owned · sample retail value','chart'],['Active reservations',count('Reserved'),'holds','Protected across all channels','shield']].map(([label,val,unit,note,ic])=>`<div class="stat"><div class="stat-top">${label}${icon(ic)}</div><strong>${val} <small>${unit}</small></strong><div class="stat-foot">${note}</div></div>`).join('')}</div>`}
function stockTable(list){return `<div class="table-wrap"><table><thead><tr><th>PIECE / DESIGN</th><th>PURITY & WEIGHT</th><th>LOCATION</th><th>VALUE</th><th>AVAILABILITY</th><th></th></tr></thead><tbody>${list.length?list.map(i=>`<tr><td><div class="piece-cell"><span class="piece-icon">${icon('diamond')}</span><div><strong>${i.name}</strong><span class="sub">${i.id} · ${i.category}</span></div></div></td><td>${i.purity}<span class="sub">${i.weight.toFixed(3)} g gross</span></td><td>${i.branch}<span class="sub">${i.status==='In transit'?'Transit custody':'Showroom · '+i.owner+' owned'}</span></td><td>${fmt(i.value)}</td><td>${badge(i.status)}</td><td><button class="icon-button" aria-label="View ${i.name}" onclick="piece('${i.id}')">${icon('arrow')}</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No pieces match your filters.</td></tr>'}</tbody></table></div>`}
function channels(){return [['store','Showroom POS','Puttur pilot · central reservation','Connected'],['globe','Online store','Stock verified · 10:38 AM','Connected'],['sync','Reconciliation',syncRetried?'All sample records aligned':'1 listing requires review',syncRetried?'Aligned':'1 mismatch']].map(([ic,note,sub,state])=>`<div class="channel"><div class="channel-symbol">${icon(ic)}</div><div class="channel-info"><b>${note}</b><small>${sub}</small></div>${badge(state)}</div>`).join('')}
function overview(){const av=count('Available'),rs=count('Reserved'),tr=count('In transit');return heading('Every piece. One clear view.','Your inventory across showrooms and online, in one place.',`<span style="font-size:12px;color:#7b897d">18 September 2026</span>${btn('View inventory',"go('inventory')",true,'arrow')}`)+`<div class="status-strip"><span><span class="live-dot"></span><strong>Pilot channels connected</strong> <span style="margin:0 12px;color:#bac8b8">|</span> Demo snapshot · 10:45 AM IST</span><small>Central reservations protected</small></div>`+stats()+`<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Inventory composition</h2><p>Distinct pieces, with no overlapping counts</p></div><span class="badge gray">All branches</span></div><div class="chart-layout"><div class="donut" style="background:conic-gradient(#285444 0 ${av/16*100}%,#bd9d62 ${av/16*100}% ${(av+rs)/16*100}%,#9baea0 ${(av+rs)/16*100}% ${(av+rs+tr)/16*100}%,#e7eae2 ${(av+rs+tr)/16*100}% 100%)"><div class="donut-label"><strong>16</strong><span>Total pieces</span></div></div><div class="legend">${[['Available to sell',av,'#285444'],['Reserved',rs,'#bd9d62'],['In transit',tr,'#9baea0'],['Quarantine',count('Quarantine'),'#e7eae2']].map(([s,n,c])=>`<div class="legend-row"><i style="background:${c}"></i>${s}<b>${n.toString().padStart(2,'0')}</b><small>${Math.round(n/16*100)}%</small></div>`).join('')}</div></div><div class="panel-foot"><span>Ownership and custody tracked independently</span>${icon('shield')}</div></section><section class="panel"><div class="panel-head"><div><h2>Channel health</h2><p>A connected view of your selling channels</p></div><button class="text" onclick="go('channels')">Manage ${icon('arrow')}</button></div>${channels()}<div class="panel-foot"><span>External display and reservation are separate controls</span></div></section></div><section class="panel"><div class="panel-head"><div><h2>A closer look at your collection</h2><p>Featured pieces from across the network</p></div><button class="text" onclick="go('inventory')">View all pieces ${icon('arrow')}</button></div>${stockTable(items.slice(0,4))}<div class="table-footer"><span>Showing 4 of 16 pieces</span><span>Sample retail values · INR</span></div></section><div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Stock across branches</h2><p>Physical pieces assigned to each location</p></div>${icon('store')}</div>${branches.map(b=>`<div class="branch-row"><span class="branch-name">${b}</span><div class="bar"><i style="width:${items.filter(i=>i.branch===b&&i.status!=='In transit').length/5*100}%"></i></div><b>${items.filter(i=>i.branch===b&&i.status!=='In transit').length}</b></div>`).join('')}<div class="panel-foot">${count('In transit')} piece in transit custody, excluded from branch totals</div></section><section class="panel"><div class="panel-head"><h2>Latest movements</h2>${icon('clock')}</div>${history.slice(0,3).map(([ic,t,sub,time])=>`<div class="activity">${icon(ic)}<div><p>${t}</p><small>${sub} · ${time}</small></div></div>`).join('')}</section></div>`}
function inventory(){return heading('The collection, accounted for.','Trace every piece from inward receipt to its next destination.',btn('Export stock',"exportStock()",false,'download')+btn('Reserve a piece',"reserveForm()",true,'plus'))+stats()+`<section class="panel"><div class="panel-head"><h2>Piece inventory</h2><span class="badge gray">16 registered pieces</span></div><div class="table-toolbar"><input class="search" aria-label="Search inventory" placeholder="Search design or piece ID…" value="${safe(filter.query)}" oninput="filter.query=this.value;updateTable()"><select aria-label="Filter branch" onchange="filter.branch=this.value;updateTable()">${['All branches',...branches].map(s=>`<option ${filter.branch===s?'selected':''}>${s}</option>`).join('')}</select><select aria-label="Filter status" onchange="filter.status=this.value;updateTable()">${['All statuses','Available','Reserved','In transit','Quarantine'].map(s=>`<option ${filter.status===s?'selected':''}>${s}</option>`).join('')}</select><button onclick="filter={query:'',status:'All statuses',branch:'All branches'};render()">Reset</button></div><div id="stock-table">${stockTable(filtered())}</div><div class="table-footer"><span id="result-count">${filtered().length} matching pieces</span><span>Click a piece to inspect its history</span></div></section>`}
function filtered(){return items.filter(i=>(i.name+' '+i.id).toLowerCase().includes(filter.query.toLowerCase())&&(filter.branch==='All branches'||i.branch===filter.branch)&&(filter.status==='All statuses'||i.status===filter.status))}
function updateTable(){document.getElementById('stock-table').innerHTML=stockTable(filtered());document.getElementById('result-count').textContent=filtered().length+' matching pieces'}
function modal(title,body){document.getElementById('dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" onclick="closeModal()" aria-label="Close dialog">${icon('close')}</button></div>${body}`;document.getElementById('dialog').showModal()}
function closeModal(){document.getElementById('dialog').close()}
function piece(id){const i=items.find(x=>x.id===id);modal(i.name,`${badge(i.status)}<div class="detail-grid">${[['Piece identity',i.id],['Category',i.category],['Purity',i.purity],['Gross weight',i.weight.toFixed(3)+' g'],['Ownership',i.owner],['Custody',i.status==='In transit'?'Transit · SEAL-0841':i.branch+' showroom'],['Original stock age',i.age+' days'],['Sample retail value',fmt(i.value)],['Design / variant','DES-'+i.id.slice(4)+' / V01'],['Publication',i.status==='Available'?'Eligible':'Excluded']].map(([l,v])=>`<div><label>${l}</label><b>${v}</b></div>`).join('')}</div><h2>Piece timeline</h2><div class="timeline"><p>Identity registered and inward recorded<small>Inventory operator · Original receipt preserved</small></p><p>${i.status==='Quarantine'?'Inspection pending — retail publication blocked':'Quality inspection accepted'}<small>${i.branch} · Sample inspection record</small></p><p>Current position: ${i.status}<small>Central ledger · Demo record</small></p></div>${i.status==='Available'?btn('Reserve this piece',`closeModal();reserveForm('${id}')`,true,'shield'):'<div class="notice">This piece is not available for a new reservation.</div>'}`)}
function reserveForm(id=''){modal('Create a reservation',`<p>Place an eligible piece on hold across the demo channels.</p><form onsubmit="event.preventDefault();saveReservation(this)"><label class="form-field">Piece<select name="piece" required>${items.filter(i=>i.status==='Available').map(i=>`<option value="${i.id}" ${id===i.id?'selected':''}>${i.id} · ${i.name}</option>`).join('')}</select></label><label class="form-field">Sales channel<select name="channel"><option>Showroom</option><option>Website</option><option>Store pickup</option><option>WhatsApp assisted</option></select></label><label class="form-field">Customer reference<input name="customer" required maxlength="40" placeholder="e.g. Customer 023"></label><div class="notice">Demo hold only. The piece becomes unavailable elsewhere in this session. Production reservation expiry and concurrency require a central server.</div><div class="dialog-actions">${btn('Cancel','closeModal()')}<button class="primary" type="submit">Confirm reservation</button></div></form>`)}
function safe(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function saveReservation(f){const i=items.find(i=>i.id===f.piece.value);if(!i||i.status!=='Available'){toast('This piece is no longer available.');return}i.status='Reserved';holds.push({id:'RSV-'+(1084+holds.length),piece:i.id,channel:f.channel.value,customer:safe(f.customer.value),state:'Payment pending'});history.unshift(['shield','Piece reserved',i.id+' · '+f.channel.value,'Just now']);closeModal();render();toast('Reservation created. Piece protected in this demo session.')}
function reservations(){return heading('A promise, protected.','Central holds, payment states and fulfilment in one queue.',btn('New reservation','reserveForm()',true,'plus'))+`<div class="status-strip"><span>${count('Reserved')} active holds · No conflicting demo reservations</span><small>Payment and physical custody are independent</small></div><section class="panel"><div class="panel-head"><h2>Reservations & orders</h2><span class="badge gray">Session demo</span></div><div class="table-wrap"><table><thead><tr><th>RESERVATION / PIECE</th><th>CHANNEL</th><th>CUSTOMER</th><th>PAYMENT STATE</th><th>ACTION</th></tr></thead><tbody>${holds.map(h=>`<tr><td><strong>${h.id}</strong><span class="sub">${h.piece} · ${items.find(i=>i.id===h.piece).name}</span></td><td>${h.channel}</td><td>${h.customer}</td><td>${badge(h.state)}</td><td>${h.state==='Cancelled'?'<span class="sub">Hold released</span>':btn('Review',`reviewHold('${h.id}')`)}</td></tr>`).join('')}</tbody></table></div></section><div class="bottom-grid"><div class="panel workflow-card"><span class="badge amber">Payment exception</span><h2>Payment received after hold expired</h2><p>EXC-009 · Website order WEB-3201. The original piece has a newer reservation. Customer service must review an alternative or refund.</p>${btn('Review exception',"exceptionDetail()")}</div><div class="panel workflow-card"><span class="badge gray">Fulfilment policy</span><h2>One piece, one commitment</h2><p>Picking, dispatch, payment and stock release are separate steps. A cancelled dispatched order must follow the return and inspection workflow.</p></div></div>`}
function reviewHold(id){const h=holds.find(h=>h.id===id);modal(h.id,`<p>${h.piece} · ${h.customer}</p><div class="detail-grid"><div><label>Channel</label><b>${h.channel}</b></div><div><label>Payment</label>${badge(h.state)}</div></div><div class="notice">${h.state==='Deposit received'?'A deposit has been received. Cancellation requires finance review; this demo does not release paid holds.':'This unpaid, unpicked demo hold can be cancelled and released.'}</div><div class="dialog-actions">${btn('Close','closeModal()')}${h.state==='Payment pending'?btn('Cancel unpaid hold',`cancelHold('${id}')`):''}</div>`)}
function cancelHold(id){const h=holds.find(h=>h.id===id);h.state='Cancelled';items.find(i=>i.id===h.piece).status='Available';history.unshift(['shield','Unpaid hold cancelled',h.piece,'Just now']);closeModal();render();toast('Unpaid hold cancelled; piece is available again.')}
function exceptionDetail(){modal('Payment exception · EXC-009',`<p>Paid but unallocated · Website WEB-3201</p><div class="detail-grid"><div><label>Payment reference</label><b>PAY-DEMO-291</b></div><div><label>Owner</label><b>Customer service + finance</b></div><div><label>Expected state</label><b>Paid, eligible piece allocated</b></div><div><label>Actual state</label><b>Piece held by a newer reservation</b></div></div><div class="notice">The newer hold stays protected. Finance must verify the payment before approving an alternative or refund. No payment action is performed by this prototype.</div><div class="dialog-actions">${btn('Close','closeModal()')}</div>`)}
function transferPage(){return heading('Care in every handover.','Follow each piece through request, dispatch and approved receipt.',btn('Request transfer','transferForm()',true,'plus'))+`<section class="panel"><div class="panel-head"><h2>Branch movements</h2><p>Custody stays accountable at every step</p></div><div class="table-wrap"><table><thead><tr><th>TRANSFER</th><th>PIECE</th><th>JOURNEY</th><th>SEAL / REFERENCE</th><th>STATE</th><th>ACTION</th></tr></thead><tbody>${transfers.map(t=>`<tr><td>${t.id}</td><td>${t.piece}</td><td>${t.from} → ${t.to}</td><td>${t.seal}</td><td>${badge(t.state)}</td><td>${btn('Inspect',`transferDetail('${t.id}')`)}</td></tr>`).join('')}</tbody></table></div></section><div class="rate-banner" style="margin-top:24px"><div><div class="eyebrow">CHAIN OF CUSTODY</div><h2>Requested → Approved → Dispatched → Received</h2><p style="margin-top:10px">Destination availability starts only after receipt and inspection.</p></div>${icon('shield')}</div>`}
function transferForm(){modal('Request a branch transfer',`<form onsubmit="event.preventDefault();saveTransfer(this)"><label class="form-field">Available piece<select name="piece">${items.filter(i=>i.status==='Available').map(i=>`<option value="${i.id}">${i.id} · ${i.branch} · ${i.name}</option>`).join('')}</select></label><label class="form-field">Destination<select name="destination">${branches.map(b=>`<option>${b}</option>`).join('')}</select></label><label class="form-field">Reason<input name="reason" required placeholder="e.g. Customer appointment" maxlength="120"></label><div class="notice">A request does not move stock. Manager approval is required before movement allocation.</div><div class="dialog-actions"><button class="primary">Submit request</button></div></form>`)}
function saveTransfer(f){const i=items.find(i=>i.id===f.piece.value);if(i.branch===f.destination.value){toast('Choose a different destination branch.');return}if(transfers.some(t=>t.piece===i.id&&t.state!=='Received')){toast('An open transfer already exists for this piece.');return}transfers.push({id:'TRF-'+(282+transfers.length-1),piece:i.id,from:i.branch,to:f.destination.value,state:'Pending approval',seal:'Not dispatched',reason:safe(f.reason.value)});closeModal();render();toast('Transfer request submitted for manager review.')}
function transferDetail(id){const t=transfers.find(t=>t.id===id);modal(t.id,`<p>${t.piece} · ${t.from} → ${t.to}</p><div class="detail-grid"><div><label>State</label>${badge(t.state)}</div><div><label>Seal reference</label><b>${t.seal}</b></div></div>${t.state==='In transit'?`<form onsubmit="event.preventDefault();receiveTransfer('${id}',this)"><label class="form-field">Scan / enter the exact piece ID<input name="scan" required placeholder="${t.piece}"></label><label class="form-field"><span><input type="checkbox" name="checked" required> Seal, condition and weight inspection accepted</span></label><div class="dialog-actions"><button class="primary">Confirm demo receipt</button></div></form>`:`<div class="notice">${t.state==='Received'?'Receipt accepted. Custody and destination availability updated.':'Pending independent manager review. No physical stock movement has occurred.'}</div>`}`)}
function receiveTransfer(id,f){const t=transfers.find(t=>t.id===id);if(f.scan.value.trim()!==t.piece){toast('Wrong piece. Enter the exact dispatched piece ID.');return}const i=items.find(i=>i.id===t.piece);i.branch=t.to;i.status='Available';t.state='Received';history.unshift(['transfer','Transfer received and inspected',t.id+' · '+t.to,'Just now']);closeModal();render();toast('Receipt accepted. Piece available at '+t.to+'.')}
function channelPage(){return heading('Connected, with confidence.','Monitor publication, delivery and reconciliation separately.',btn('Run demo reconciliation','reconcile()',true,'sync'))+`<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Connected pilot channels</h2><span class="badge gray">Simulated</span></div>${channels()}</section><section class="panel workflow-card"><div class="eyebrow">SYNC HEALTH · SAMPLE</div><h2>Central → delivered → verified</h2><div class="detail-grid"><div><label>Last verified snapshot</label><b>10:38 AM IST</b></div><div><label>Demo queue backlog</label><b>${syncRetried?'0':'1'} event</b></div><div><label>Central conflicts</label><b>0 in sample records</b></div><div><label>Verification status</label>${badge(syncRetried?'Aligned':'Review pending')}</div></div><p>Acknowledging an event does not prove the external listing has changed.</p></section></div><section class="panel"><div class="panel-head"><h2>Reconciliation exceptions</h2><span class="badge ${syncRetried?'':'amber'}">${syncRetried?'0 open':'1 open'}</span></div>${syncRetried?'<div class="empty">All demo channel records are aligned. No open sync exceptions.</div>':`<div class="table-wrap"><table><thead><tr><th>PIECE / CHANNEL</th><th>CENTRAL</th><th>WEBSITE</th><th>CAUSE</th><th>ACTION</th></tr></thead><tbody><tr><td>GDI-2403<span class="sub">Website · EVT-0841 · version 8</span></td><td>Reserved · 0 available</td><td>1 available</td><td>${badge('Delayed event')}</td><td>${btn('Review & retry','retryDetail()')}</td></tr></tbody></table></div>`}</section>`}
function retryDetail(){modal('Reconcile GDI-2403',`<p>The authoritative central state is reserved. The website sample still shows one available piece.</p><div class="detail-grid"><div><label>Last successful version</label><b>7</b></div><div><label>Expected version</label><b>8</b></div><div><label>Pending order check</label><b>No unmatched demo orders</b></div><div><label>Previous attempts</label><b>1 · simulated timeout</b></div></div><div class="notice">Retry republishes central availability in this demo only. It does not change the stock ledger or contact a real website.</div><div class="dialog-actions">${btn('Retry demo event','syncRetried=true;closeModal();render();toast("Demo event replayed and external sample verified.")',true)}</div>`)}
function reconcile(){if(!syncRetried){retryDetail()}else toast('Demo reconciliation complete. All sample records match.')}
function inwardPage(){return heading('A considered beginning.','Receipt, inspection and acceptance before anything goes on sale.')+`<div class="section-grid">${[['PO-0921','Shree Jewellery Works','Partial receipt','12 ordered · 8 received','4 pieces outstanding'],['GRN-0418','Supplier consignment','Quarantine','GDI-2414 · Pearl Gold Choker','32.450 g · Documentation pending'],['QC-0219','Weight discrepancy','Review pending','Expected 18.500 g · received 18.320 g','0.180 g variance · Inspector review']].map(([id,n,s,a,b])=>`<section class="panel workflow-card"><div class="eyebrow">${id}</div>${badge(s)}<h2>${n}</h2><p>${a}</p><div class="meta">${b}</div>${btn('View receipt',`receipt('${id}')`)}</section>`).join('')}</div><div class="notice" style="margin-top:24px">Received stock remains separate from saleable stock. Supplier-owned consignment is excluded from company-owned valuation.</div>`}
function receipt(id){modal(id,`<p>Demonstration procurement record</p><div class="timeline"><p>Purchase / consignment reference captured<small>Supplier source document retained</small></p><p>Physical receipt recorded<small>Piece count, gross weight and ownership captured</small></p><p>Inspection and document review<small>Inspector: Meera S. · Inventory quality team</small></p><p>Availability release pending<small>Only accepted, fully identified pieces may be published</small></p></div><div class="notice">This record is read-only in the prototype. Acceptance, financial matching and exception approval remain separate decisions.</div>`)}
function servicePage(){return heading('Aftercare, with a complete history.','Keep customer property, returns and material lineage distinct.')+`<div class="section-grid">${[['RET-0042','Cross-channel return','Inspection pending','Original order WEB-3188','Refund review and stock inspection are separate.'],['REP-0087','Ring resizing','With service vendor','Customer-owned · 4.850 g inward','Excluded from company stock and retail availability.'],['JOB-0021','Gold remaking','Review pending','Material lot LOT-0039 · 24.000 g','New output identities preserve original material lineage.']].map(([id,title,s,ref,note])=>`<section class="panel workflow-card"><span class="eyebrow">${id}</span><div>${badge(s)}</div><h2>${title}</h2><p>${ref}</p><div class="meta">${note}</div>${btn('View service record',`serviceDetail('${id}','${title}')`)}</section>`).join('')}</div>`}
function serviceDetail(id,title){modal(title,`<p>${id} · Sample service record</p><div class="detail-grid"><div><label>Owner</label><b>${id.startsWith('REP')?'Customer':'Company / pending inspection'}</b></div><div><label>Operational owner</label><b>Service desk · Puttur</b></div><div><label>Promised review</label><b>21 September 2026</b></div><div><label>Retail availability</label><b>Blocked</b></div></div><div class="timeline"><p>Intake reference and condition captured<small>Original identity and ownership retained</small></p><p>Work / inspection in progress<small>Before-and-after weight evidence required</small></p><p>Quality review and disposition pending<small>No automatic stock release or refund</small></p></div>`)}
function auditsPage(){return heading('Trust, backed by a trail.','Independent review for every sensitive inventory decision.')+`<div class="dashboard-grid"><section class="panel workflow-card"><div class="eyebrow">AUD-0031 / PUTTUR</div><h2>September cycle count</h2><p style="margin-top:10px">Gold counter · 4 baseline pieces · 3 verified · 1 recount pending</p><div class="bar" style="margin:22px 0"><i style="width:75%"></i></div><div class="meta"><span>Counter</span><b>Ravi K.</b></div><div class="meta"><span>Independent reviewer</span><b>Meera S.</b></div>${btn('Inspect variance',"auditDetail()")}</section><section class="panel workflow-card"><div class="eyebrow">APP-0072 / ADJUSTMENT</div><h2>Location correction</h2><p style="margin-top:10px">GDI-2405 · Counter A → Vault 2. The original count and custody event remain in history.</p><div class="meta"><span>Requested by</span><b>Ananya Kumar</b></div><div class="meta"><span>State</span>${badge(approvalDone?'Escalated':'Pending approval')}</div><div class="notice">You are the requester. A different authorised manager must approve.</div>${btn('Send for independent review','approvalDone=true;render();toast("Demo request assigned to independent reviewer Meera S.")')}</section></div><section class="panel"><div class="panel-head"><h2>Recent audit trail</h2><span class="badge gray">Session activity</span></div>${history.map(([ic,t,sub,time])=>`<div class="activity">${icon(ic)}<div><p>${t}</p><small>${sub} · ${time}</small></div></div>`).join('')}</section>`}
function auditDetail(){modal('Variance · AUD-0031',`<p>GDI-2405 · Location mismatch</p><div class="detail-grid"><div><label>Expected custody</label><b>Puttur · Counter A</b></div><div><label>Observed location</label><b>Puttur · Vault 2</b></div><div><label>Original count</label><b>Retained · 18 Sep, 09:30</b></div><div><label>Disposition</label><b>Independent recount pending</b></div></div><div class="notice">A count does not change the stock ledger. Evidence and independent approval are required for a correction.</div>`)}
function reports(){const buckets=[['0–30 days',i=>i.age<=30],['31–60 days',i=>i.age>30&&i.age<=60],['61–90 days',i=>i.age>60&&i.age<=90],['90+ days',i=>i.age>90]];return heading('Perspective for the next decision.','Stock ageing, ownership and value across the network.',btn('Export inventory report','exportStock()',true,'download'))+stats()+`<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Original stock ageing</h2><p>Age is preserved across branch transfers</p></div></div>${buckets.map(([label,test])=>`<div class="branch-row"><span class="branch-name">${label}</span><div class="bar"><i style="width:${items.filter(test).length/8*100}%"></i></div><b>${items.filter(test).length}</b></div>`).join('')}<div class="panel-foot">16 registered pieces · Includes supplier-owned and transit stock</div></section><section class="panel workflow-card"><div class="eyebrow">VALUATION BASIS</div><h2>Sample retail value</h2><p style="margin-top:12px">All displayed values use the prototype's sample retail prices. They are not acquisition cost, accounting valuation or live metal rates.</p><div class="meta"><span>Company-owned</span><b>${items.filter(i=>i.owner==='Company').length} pieces</b></div><div class="meta"><span>Supplier consignment</span><b>${items.filter(i=>i.owner==='Supplier').length} piece</b></div><div class="meta"><span>Customer service property</span><b>Excluded</b></div></section></div>`}
function exportStock(){const rows=[['Piece ID','Design','Category','Purity','Gross weight g','Branch','Ownership','Status','Sample retail INR','Age days'],...(route==='reports'?items:filtered()).map(i=>[i.id,i.name,i.category,i.purity,i.weight,i.branch,i.owner,i.status,i.value,i.age])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='gold-diamonds-demo-inventory.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Demo inventory exported as CSV.')}
function render(){route=location.hash.slice(1)||'overview';if(!nav.some(n=>n[0]===route))route='overview';document.getElementById('nav').innerHTML=nav.map(([r,n,ic],i)=>`${i===5?'<div class="nav-section">CONTROL & INTELLIGENCE</div>':''}<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(ic)}${n}${r==='channels'&&!syncRetried?'<span class="count">1</span>':''}</a>`).join('');document.getElementById('crumb').textContent=nav.find(n=>n[0]===route)[1];document.getElementById('main').innerHTML=({overview,inventory,reservations,transfers:transferPage,inward:inwardPage,channels:channelPage,service:servicePage,audits:auditsPage,reports}[route])();}
document.getElementById('alerts').innerHTML=icon('bell');document.getElementById('alerts').onclick=exceptionDetail;document.getElementById('dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
